  SELECT * FROM JSON_TABLE('[{"t":"dp_pull_dp10_stage_cleanup","n":"chk_dp10_cleanup_generation"},{"t":"dp_pull_dp10_stage_cleanup","n":"chk_dp10_cleanup_reason"},{"t":"dp_pull_dp10_stage_cleanup","n":"chk_dp10_cleanup_fence"},{"t":"dp_pull_scope_admission","n":"chk_dp_scope_admission_identity"},{"t":"dp_pull_scope_admission","n":"chk_dp_scope_admission_kind"},{"t":"dp_pull_scope_admission","n":"chk_dp_scope_admission_digest"}]', '$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t', constraint_name VARCHAR(64) PATH '$.n')) AS j
),
contract_check AS (SELECT * FROM contract_check_base UNION ALL
  SELECT * FROM JSON_TABLE('[{"t":"dp_pull_snapshot_apply","n":"chk_dp_snapshot_apply_accounting"},{"t":"dp_pull_report_artifact","n":"chk_dp_report_artifact_download_state"},{"t":"dp_pull_report_artifact","n":"chk_dp_report_artifact_chunk_count"},{"t":"dp_pull_report_artifact","n":"chk_dp_report_artifact_storage_shape"}]', '$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t', constraint_name VARCHAR(64) PATH '$.n')) AS j
),
contract_fk AS (SELECT * FROM expected_fk UNION ALL
  SELECT * FROM JSON_TABLE('[{"t":"dp_pull_dp10_stage_cleanup","n":"fk_dp10_cleanup_task","c":"task_id","r":"dp_pull_task","rc":"id","d":"NO ACTION","u":"NO ACTION"},{"t":"dp_pull_schedule_anchor","n":"fk_dp_schedule_anchor_admission","c":"scope_key,cutover_key","r":"dp_pull_scope_admission","rc":"scope_key,cutover_key","d":"NO ACTION","u":"NO ACTION"}]', '$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t', constraint_name VARCHAR(64) PATH '$.n', child_columns VARCHAR(1000) PATH '$.c', referenced_table_name VARCHAR(64) PATH '$.r', referenced_columns VARCHAR(1000) PATH '$.rc', delete_rule VARCHAR(16) PATH '$.d', update_rule VARCHAR(16) PATH '$.u')) AS j
),
binding_column AS (
  SELECT * FROM JSON_TABLE('[{"t":"dp_pull_task","n":"scope_binding_id","y":"char(64)","q":"YES","s":"ascii","o":"ascii_bin","d":"-"},{"t":"dp_pull_task","n":"scope_payload_type","y":"varchar(64)","q":"YES","s":"utf8mb4","o":"utf8mb4_bin","d":"-"},{"t":"dp_pull_task","n":"scope_payload_sha256","y":"char(64)","q":"YES","s":"ascii","o":"ascii_bin","d":"-"},{"t":"dp_pull_task","n":"scope_payload","y":"mediumtext","q":"YES","s":"utf8mb4","o":"utf8mb4_bin","d":"-"},{"t":"dp_pull_task","n":"scope_binding_effective_from_utc","y":"datetime(3)","q":"YES","s":"","o":"","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"binding_id","y":"char(64)","q":"NO","s":"ascii","o":"ascii_bin","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"operation_code","y":"varchar(16)","q":"NO","s":"utf8mb4","o":"utf8mb4_bin","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"scope_key","y":"varchar(96)","q":"NO","s":"utf8mb4","o":"utf8mb4_bin","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"payload_type","y":"varchar(64)","q":"NO","s":"utf8mb4","o":"utf8mb4_bin","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"payload_sha256","y":"char(64)","q":"NO","s":"ascii","o":"ascii_bin","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"payload","y":"mediumtext","q":"NO","s":"utf8mb4","o":"utf8mb4_bin","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"effective_from_utc","y":"datetime(3)","q":"NO","s":"","o":"","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"effective_until_utc","y":"datetime(3)","q":"YES","s":"","o":"","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"source_observed_at_utc","y":"datetime(3)","q":"NO","s":"","o":"","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"open_scope_slot","y":"varchar(113)","q":"YES","s":"utf8mb4","o":"utf8mb4_bin","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"gmt_create","y":"datetime(3)","q":"NO","s":"","o":"","d":"-"},{"t":"dp_pull_scope_binding_epoch","n":"gmt_updated","y":"datetime(3)","q":"NO","s":"","o":"","d":"-"}]', '$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t', column_name VARCHAR(64) PATH '$.n', column_type VARCHAR(64) PATH '$.y', is_nullable VARCHAR(3) PATH '$.q', character_set_name VARCHAR(64) PATH '$.s', collation_name VARCHAR(64) PATH '$.o', default_signature VARCHAR(100) PATH '$.d')) AS j
), binding_index AS (
  SELECT * FROM JSON_TABLE('[{"t":"dp_pull_task","n":"idx_dp_pull_task_scope_binding","u":1,"c":"scope_binding_id"},{"t":"dp_pull_scope_binding_epoch","n":"PRIMARY","u":0,"c":"binding_id"},{"t":"dp_pull_scope_binding_epoch","n":"uk_dp_scope_binding_start","u":0,"c":"operation_code,scope_key,effective_from_utc"},{"t":"dp_pull_scope_binding_epoch","n":"uk_dp_scope_binding_open","u":0,"c":"open_scope_slot"},{"t":"dp_pull_scope_binding_epoch","n":"idx_dp_scope_binding_lookup","u":1,"c":"operation_code,scope_key,effective_from_utc,effective_until_utc,binding_id"},{"t":"dp_pull_scope_binding_epoch","n":"idx_dp_scope_binding_admission","u":1,"c":"scope_key"}]', '$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t', index_name VARCHAR(64) PATH '$.n', non_unique INT PATH '$.u', index_columns VARCHAR(1000) PATH '$.c')) AS j
), binding_check AS (
  SELECT * FROM JSON_TABLE('[{"t":"dp_pull_task","n":"chk_dp_pull_task_scope_binding"},{"t":"dp_pull_scope_binding_epoch","n":"chk_dp_scope_binding_operation"},{"t":"dp_pull_scope_binding_epoch","n":"chk_dp_scope_binding_identity"},{"t":"dp_pull_scope_binding_epoch","n":"chk_dp_scope_binding_time"},{"t":"dp_pull_scope_binding_epoch","n":"chk_dp_scope_binding_open"}]', '$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t', constraint_name VARCHAR(64) PATH '$.n')) AS j
), binding_fk AS (
  SELECT * FROM JSON_TABLE('[{"t":"dp_pull_task","n":"fk_dp_pull_task_scope_binding","c":"scope_binding_id","r":"dp_pull_scope_binding_epoch","rc":"binding_id","d":"NO ACTION","u":"NO ACTION"},{"t":"dp_pull_scope_binding_epoch","n":"fk_dp_scope_binding_admission","c":"scope_key","r":"dp_pull_scope_admission","rc":"scope_key","d":"NO ACTION","u":"NO ACTION"}]', '$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t', constraint_name VARCHAR(64) PATH '$.n', child_columns VARCHAR(1000) PATH '$.c', referenced_table_name VARCHAR(64) PATH '$.r', referenced_columns VARCHAR(1000) PATH '$.rc', delete_rule VARCHAR(16) PATH '$.d', update_rule VARCHAR(16) PATH '$.u')) AS j
),
contract_column_all AS (SELECT * FROM contract_column UNION ALL SELECT * FROM binding_column), contract_index_all AS (SELECT * FROM contract_index UNION ALL SELECT * FROM binding_index),
contract_check_all AS (SELECT * FROM contract_check UNION ALL SELECT * FROM binding_check), contract_fk_all AS (SELECT * FROM contract_fk UNION ALL SELECT * FROM binding_fk),
actual_column AS (SELECT c.table_name, c.column_name, LOWER(c.column_type) AS column_type, c.is_nullable,
    COALESCE(LOWER(c.character_set_name), '') AS character_set_name,
    COALESCE(LOWER(c.collation_name), '') AS collation_name,
    CASE WHEN c.column_default IS NULL THEN '-'
      WHEN c.data_type='bit' AND LOWER(c.column_default) IN ('0', 'b''0''') THEN '0'
      ELSE LOWER(c.column_default) END AS default_signature,
    LOWER(c.extra) AS extra, c.generation_expression
  FROM information_schema.columns c JOIN contract_table e ON e.table_name=c.table_name
  WHERE c.table_schema=DATABASE()
),
actual_index AS (SELECT s.table_name, s.index_name, MIN(s.non_unique) AS non_unique,
    GROUP_CONCAT(s.column_name ORDER BY s.seq_in_index SEPARATOR ',') AS index_columns,
    MIN(CASE WHEN s.index_type='BTREE' AND s.is_visible='YES' AND s.sub_part IS NULL
      AND s.expression IS NULL AND s.collation='A' THEN 1 ELSE 0 END) AS safe_shape
  FROM information_schema.statistics s JOIN contract_table e ON e.table_name=s.table_name
  WHERE s.table_schema=DATABASE() GROUP BY s.table_name, s.index_name
),
actual_check AS (SELECT c.table_name, c.constraint_name, c.enforced, REGEXP_REPLACE(LOWER(cc.check_clause),'[`[:space:]]+','') AS check_clause
  FROM information_schema.table_constraints c JOIN contract_table e ON e.table_name=c.table_name JOIN information_schema.check_constraints cc ON cc.constraint_schema=c.constraint_schema AND cc.constraint_name=c.constraint_name
  WHERE c.constraint_schema=DATABASE() AND c.constraint_type='CHECK'
),
actual_fk AS (SELECT k.table_name, k.constraint_name,
    GROUP_CONCAT(k.column_name ORDER BY k.ordinal_position SEPARATOR ',') AS child_columns,
    MAX(k.referenced_table_name) AS referenced_table_name,
    GROUP_CONCAT(k.referenced_column_name ORDER BY k.ordinal_position SEPARATOR ',') AS referenced_columns,
    MAX(r.delete_rule) AS delete_rule, MAX(r.update_rule) AS update_rule
  FROM information_schema.key_column_usage k
  JOIN information_schema.referential_constraints r
    ON r.constraint_schema=k.constraint_schema AND r.constraint_name=k.constraint_name
  JOIN contract_table e ON e.table_name=k.table_name
  WHERE k.constraint_schema=DATABASE() AND k.referenced_table_name IS NOT NULL
  GROUP BY k.table_name, k.constraint_name
),
snapshot_page_shape AS (SELECT p.task_id, p.page_no, p.next_page, p.is_last_page, p.total_pages, p.item_count,
    p.source_item_count, p.business_skipped_item_count,
    COUNT(i.item_ordinal) AS actual_count, MIN(i.item_ordinal) AS first_ordinal, MAX(i.item_ordinal) AS last_ordinal
  FROM dp_pull_snapshot_stage_page p LEFT JOIN dp_pull_snapshot_stage_item i
    ON i.task_id=p.task_id AND i.page_no=p.page_no
  GROUP BY p.task_id, p.page_no, p.next_page, p.is_last_page, p.total_pages, p.item_count,
    p.source_item_count, p.business_skipped_item_count
),
dp10_page_shape AS (SELECT p.task_id, p.generation_no, p.scan_pass, p.partition_name, p.page_no, p.raw_row_count,
    COUNT(i.item_ordinal) AS actual_count, MIN(i.item_ordinal) AS first_ordinal, MAX(i.item_ordinal) AS last_ordinal
  FROM dp_pull_dp10_stage_page p LEFT JOIN dp_pull_dp10_stage_item i
    ON i.task_id=p.task_id AND i.generation_no=p.generation_no AND i.scan_pass=p.scan_pass
      AND i.partition_name=p.partition_name AND i.page_no=p.page_no
  GROUP BY p.task_id, p.generation_no, p.scan_pass, p.partition_name, p.page_no, p.raw_row_count
),
dp10_fingerprint_actual AS (SELECT task_id, generation_no, partition_name, list_content_fingerprint,
    SUM(scan_pass=1) AS pass_one_count, SUM(scan_pass=2) AS pass_two_count
  FROM dp_pull_dp10_stage_item
  GROUP BY task_id, generation_no, partition_name, list_content_fingerprint
),
cleanup_marker_task AS (SELECT m.task_id AS marker_task_id,m.generation_no,m.reason,m.active_fence_epoch,
    t.id AS task_id,t.operation_code,t.state,t.step_code,t.fence_epoch,t.finished_at,
    t.lease_owner,t.lease_until,IF(JSON_VALID(t.checkpoint),t.checkpoint,'{}') AS checkpoint_json
  FROM dp_pull_dp10_stage_cleanup m LEFT JOIN dp_pull_task t ON t.id=m.task_id
),
cleanup_marker_shape AS (SELECT m.*,
    CASE WHEN JSON_TYPE(JSON_EXTRACT(checkpoint_json,'$.generationNo'))='INTEGER'
      AND JSON_UNQUOTE(JSON_EXTRACT(checkpoint_json,'$.generationNo')) REGEXP '^[1-9][0-9]{0,18}$'
      AND CAST(JSON_UNQUOTE(JSON_EXTRACT(checkpoint_json,'$.generationNo')) AS DECIMAL(20,0))<=9223372036854775807
      THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(checkpoint_json,'$.generationNo')) AS DECIMAL(20,0))
      ELSE NULL END AS checkpoint_generation
  FROM cleanup_marker_task m
) SELECT IF(
  (SELECT COUNT(*) FROM information_schema.tables t JOIN contract_table e ON e.table_name=t.table_name
    WHERE t.table_schema=DATABASE() AND t.table_type='BASE TABLE' AND UPPER(t.engine)='INNODB'
      AND LOWER(t.table_collation)='utf8mb4_bin')=21
  AND NOT EXISTS (
    SELECT 1 FROM contract_column_all e LEFT JOIN actual_column a
      ON a.table_name=e.table_name AND a.column_name=e.column_name
    WHERE a.table_name IS NULL OR a.column_type<>e.column_type OR a.is_nullable<>e.is_nullable
      OR a.character_set_name<>e.character_set_name OR a.collation_name<>e.collation_name
      OR a.default_signature<>e.default_signature OR a.extra<>IF(e.table_name='dp_pull_report_artifact' AND e.column_name='updated_at','default_generated','') OR a.generation_expression<>''
  )
  AND NOT EXISTS (
    SELECT 1 FROM contract_index_all e LEFT JOIN actual_index a
      ON a.table_name=e.table_name AND a.index_name=e.index_name
    WHERE a.table_name IS NULL OR a.non_unique<>e.non_unique OR a.index_columns<>e.index_columns OR a.safe_shape<>1
  )
  AND NOT EXISTS (SELECT 1 FROM contract_check_all e LEFT JOIN actual_check a ON a.table_name=e.table_name AND a.constraint_name=e.constraint_name WHERE a.table_name IS NULL OR a.enforced<>'YES')
  AND (EXISTS (SELECT 1 FROM actual_check a WHERE a.table_name='dp_pull_snapshot_stage' AND a.constraint_name='chk_dp_snapshot_stage_authority' AND a.enforced='YES' AND a.check_clause REGEXP 'authority_kindisnotnull.*authority_kindin.*authority_token_sha256isnotnull.*(authority_token_sha256regexp|regexp_like.*authority_token_sha256).*declared_collection_countisnotnull.*declared_collection_count>=0') OR EXISTS (SELECT 1 FROM actual_check a WHERE a.table_name='dp_pull_snapshot_stage' AND a.constraint_name='chk_dp_snapshot_stage_authority_v2' AND a.enforced='YES' AND a.check_clause REGEXP 'provider_authority.*complete_response.*two_pass_required.*two_pass_observation'))
  AND (EXISTS (SELECT 1 FROM actual_check a WHERE a.table_name='dp_pull_snapshot_apply' AND a.constraint_name='chk_dp_snapshot_apply_authority' AND a.enforced='YES') OR EXISTS (SELECT 1 FROM actual_check a WHERE a.table_name='dp_pull_snapshot_apply' AND a.constraint_name='chk_dp_snapshot_apply_authority_v2' AND a.enforced='YES' AND a.check_clause REGEXP 'complete_response.*two_pass_observation.*declared_collection_count>=0'))
  AND NOT EXISTS (
    SELECT 1 FROM contract_fk_all e LEFT JOIN actual_fk a
      ON a.table_name=e.table_name AND a.constraint_name=e.constraint_name
    WHERE a.table_name IS NULL OR a.child_columns<>e.child_columns
      OR a.referenced_table_name<>e.referenced_table_name OR a.referenced_columns<>e.referenced_columns
      OR a.delete_rule<>e.delete_rule OR a.update_rule<>e.update_rule
  )
  AND (SELECT COUNT(*) FROM information_schema.triggers tr JOIN contract_table e ON e.table_name=tr.event_object_table
    WHERE tr.trigger_schema=DATABASE())=0
  AND (SELECT COUNT(*) FROM information_schema.tables
    WHERE table_schema=DATABASE() AND table_name='dp_pull_auth_wait')=0
  AND NOT EXISTS (
    SELECT 1 FROM actual_column a LEFT JOIN contract_column_all e
      ON e.table_name=a.table_name AND e.column_name=a.column_name
    WHERE e.table_name IS NULL AND NOT (
      a.extra NOT LIKE '%auto_increment%'
      AND (a.is_nullable='YES' OR a.default_signature<>'-' OR a.generation_expression<>'')
    )
  )
  AND NOT EXISTS (
    SELECT 1 FROM actual_index a LEFT JOIN contract_index_all e
      ON e.table_name=a.table_name AND e.index_name=a.index_name
    WHERE e.table_name IS NULL AND NOT (a.non_unique=1 AND a.safe_shape=1)
  )
  AND NOT EXISTS (SELECT 1 FROM dp_pull_task WHERE id<=0)
  AND (SELECT COUNT(*) FROM dp_pull_runtime_leader)=1
  AND (SELECT COUNT(*) FROM dp_pull_runtime_leader WHERE runtime_name='daily_pull')=1
  AND (SELECT COUNT(*) FROM noon_pull_id_sequence WHERE sequence_name='dp_pull_task')=1
  AND (SELECT MIN(next_id) FROM noon_pull_id_sequence WHERE sequence_name='dp_pull_task')
    >=GREATEST(0, COALESCE((SELECT MAX(id) FROM dp_pull_task), 0))
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_schedule_cutover c WHERE c.state='ACTIVE'
      AND c.expected_scope_count<>(SELECT COUNT(*) FROM dp_pull_schedule_anchor a
        WHERE a.operation_code=c.operation_code AND a.cutover_key=c.cutover_key
          AND a.anchor_kind='CUTOVER_RECONCILED')
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_schedule_anchor a JOIN dp_pull_scope_admission s
      ON s.scope_key=a.scope_key AND s.cutover_key=a.cutover_key
    WHERE a.gmt_create<s.gmt_create
      OR (a.anchor_kind='CUTOVER_RECONCILED' AND s.admission_kind<>'CUTOVER_EXISTING')
      OR (a.anchor_kind='POST_CUTOVER_SCOPE' AND (s.admission_kind<>'POST_CUTOVER'
        OR a.reconcile_after_utc<>s.first_eligible_at_utc))
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_scope_binding_epoch b
    WHERE LOWER(SHA2(b.payload,256))<>b.payload_sha256
      OR b.gmt_create<>b.source_observed_at_utc OR b.gmt_updated<b.gmt_create
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_scope_binding_epoch a JOIN dp_pull_scope_binding_epoch b
      ON a.operation_code=b.operation_code AND a.scope_key=b.scope_key AND a.binding_id<b.binding_id
      AND a.effective_from_utc<COALESCE(b.effective_until_utc,'9999-12-31 23:59:59.999')
      AND b.effective_from_utc<COALESCE(a.effective_until_utc,'9999-12-31 23:59:59.999')
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_task t LEFT JOIN dp_pull_scope_binding_epoch b ON b.binding_id=t.scope_binding_id
    WHERE t.operation_code IN ('DP08A','DP08B') AND (b.binding_id IS NULL
      OR b.operation_code<>t.operation_code OR b.scope_key<>t.scope_key
      OR b.payload_type<>t.scope_payload_type OR b.payload_sha256<>t.scope_payload_sha256
      OR BINARY b.payload<>BINARY t.scope_payload OR b.effective_from_utc<>t.scope_binding_effective_from_utc
      OR t.schedule_slot<b.effective_from_utc
      OR (b.effective_until_utc IS NOT NULL AND t.schedule_slot>=b.effective_until_utc))
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_snapshot_stage s LEFT JOIN dp_pull_task t ON t.id=s.task_id
    WHERE t.id IS NULL OR t.operation_code NOT IN ('DP04','DP06','DP07A','DP08A')
      OR s.active_fence_epoch>t.fence_epoch
      OR (NOT EXISTS (SELECT 1 FROM actual_check a WHERE a.table_name='dp_pull_snapshot_stage' AND a.constraint_name='chk_dp_snapshot_stage_authority_v2' AND a.enforced='YES') AND (((s.authority_kind IS NULL AND s.authority_token_sha256 IS NULL AND s.snapshot_as_of_utc IS NULL AND s.declared_collection_count IS NULL) AND t.operation_code<>'DP08A' AND EXISTS (SELECT 1 FROM dp_pull_snapshot_stage_page p WHERE p.task_id=s.task_id)) OR NOT ((s.authority_kind IS NULL AND s.authority_token_sha256 IS NULL AND s.snapshot_as_of_utc IS NULL AND s.declared_collection_count IS NULL) OR (s.authority_kind IS NOT NULL AND s.authority_kind IN ('PAGED_GENERATION','COMPLETE_EXPORT') AND s.authority_token_sha256 IS NOT NULL AND s.authority_token_sha256 REGEXP '^[0-9a-f]{64}$' AND s.declared_collection_count IS NOT NULL AND s.declared_collection_count>=0))))
      OR (s.declared_collection_count IS NOT NULL AND (SELECT COALESCE(SUM(p.source_item_count),0) FROM dp_pull_snapshot_stage_page p WHERE p.task_id=s.task_id)>s.declared_collection_count)
  )
  AND NOT EXISTS (
    SELECT 1 FROM snapshot_page_shape p
    WHERE p.page_no<=0 OR (p.next_page IS NOT NULL AND p.next_page<>p.page_no+1)
      OR (p.total_pages IS NOT NULL AND p.total_pages<p.page_no)
      OR (p.is_last_page=b'1' AND (p.next_page IS NOT NULL OR (p.total_pages IS NOT NULL AND p.total_pages<>p.page_no)))
      OR (p.is_last_page=b'0' AND p.total_pages=p.page_no)
      OR p.actual_count<>p.item_count
      OR p.source_item_count<>p.item_count+p.business_skipped_item_count
      OR (p.item_count=0 AND (p.first_ordinal IS NOT NULL OR p.last_ordinal IS NOT NULL))
      OR (p.item_count>0 AND (p.first_ordinal<>0 OR p.last_ordinal<>p.item_count-1))
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_snapshot_apply a LEFT JOIN dp_pull_task t ON t.id=a.task_id
    WHERE t.id IS NULL OR a.operation_code<>t.operation_code OR a.scope_key<>t.scope_key
      OR a.business_window_key<>t.business_window_key OR a.applied_fence_epoch>t.fence_epoch
  )
  AND NOT EXISTS (SELECT 1 FROM dp_pull_report_artifact a WHERE NOT ((a.download_state='LEGACY_COMPLETE' AND a.content_sha256 IS NOT NULL AND a.content_length>0 AND a.content_bytes IS NOT NULL AND a.content_length=OCTET_LENGTH(a.content_bytes) AND a.persisted_chunk_count=0) OR (a.download_state='DOWNLOADING' AND a.content_sha256 IS NULL AND a.content_length=0 AND a.content_bytes IS NULL AND a.persisted_chunk_count=0) OR (a.download_state='COMPLETE' AND a.content_sha256 IS NOT NULL AND a.content_length>0 AND a.content_bytes IS NULL AND a.persisted_chunk_count=CEIL(a.content_length/1048576))))
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_report_apply a LEFT JOIN dp_pull_task t ON t.id=a.task_id
    WHERE t.id IS NULL OR a.operation_code<>t.operation_code OR a.scope_key<>t.scope_key
      OR a.business_window_key<>t.business_window_key OR a.applied_fence_epoch>t.fence_epoch
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_dp10_stage_page p LEFT JOIN dp_pull_task t ON t.id=p.task_id
    WHERE t.id IS NULL OR t.operation_code<>'DP10' OR p.active_fence_epoch>t.fence_epoch
  )
  AND NOT EXISTS (
    SELECT 1 FROM cleanup_marker_shape m
    WHERE m.task_id IS NULL OR m.operation_code<>'DP10' OR m.active_fence_epoch>m.fence_epoch
      OR (m.reason='CURRENT_GENERATION' AND (m.step_code<>'DP10_CLEANUP'
        OR m.state NOT IN ('QUEUED','RUNNING','WAITING_BACKOFF','FAILED')
        OR (m.state='FAILED' AND (m.finished_at IS NULL
          OR m.lease_owner IS NOT NULL OR m.lease_until IS NOT NULL))
        OR m.checkpoint_generation IS NULL OR m.generation_no<>m.checkpoint_generation))
      OR (m.reason='OLDER_GENERATION' AND (m.step_code<>'DP10_LIST'
        OR m.state NOT IN ('QUEUED','RUNNING','WAITING_BACKOFF','FAILED')
        OR (m.state='FAILED' AND (m.finished_at IS NULL
          OR m.lease_owner IS NOT NULL OR m.lease_until IS NOT NULL))
        OR m.checkpoint_generation IS NULL OR m.generation_no>=m.checkpoint_generation))
      OR (m.reason='FAILED_RETENTION' AND (m.state<>'FAILED' OR m.finished_at IS NULL
        OR m.lease_owner IS NOT NULL OR m.lease_until IS NOT NULL OR m.step_code NOT IN
          ('DP10_LOAD_PROGRESS','DP10_LIST','DP10_SEAL','DP10_DETAIL','DP10_VERIFY','DP10_APPLY','DP10_CLEANUP')))
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp10_page_shape p
    WHERE NOT EXISTS (SELECT 1 FROM dp_pull_dp10_stage_cleanup m
        WHERE m.task_id=p.task_id AND m.generation_no=p.generation_no)
      AND (p.actual_count<>p.raw_row_count
        OR (p.raw_row_count=0 AND (p.first_ordinal IS NOT NULL OR p.last_ordinal IS NOT NULL))
        OR (p.raw_row_count>0 AND (p.first_ordinal<>0 OR p.last_ordinal<>p.raw_row_count-1)))
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp10_fingerprint_actual a LEFT JOIN dp_pull_dp10_stage_fingerprint_count c
      ON c.task_id=a.task_id AND c.generation_no=a.generation_no AND c.partition_name=a.partition_name
        AND c.list_content_fingerprint=a.list_content_fingerprint
    WHERE NOT EXISTS (SELECT 1 FROM dp_pull_dp10_stage_cleanup m
        WHERE m.task_id=a.task_id AND m.generation_no=a.generation_no)
      AND (c.task_id IS NULL OR c.pass_one_count<>a.pass_one_count OR c.pass_two_count<>a.pass_two_count)
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_dp10_stage_fingerprint_count c LEFT JOIN dp10_fingerprint_actual a
      ON a.task_id=c.task_id AND a.generation_no=c.generation_no AND a.partition_name=c.partition_name
        AND a.list_content_fingerprint=c.list_content_fingerprint
    LEFT JOIN dp_pull_task t ON t.id=c.task_id
    WHERE NOT EXISTS (SELECT 1 FROM dp_pull_dp10_stage_cleanup m
        WHERE m.task_id=c.task_id AND m.generation_no=c.generation_no)
      AND (a.task_id IS NULL OR t.id IS NULL OR t.operation_code<>'DP10'
        OR c.pass_one_count<>a.pass_one_count OR c.pass_two_count<>a.pass_two_count)
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_dp10_stage_identity d
    LEFT JOIN dp_pull_dp10_stage_item i
      ON i.task_id=d.task_id AND i.generation_no=d.generation_no AND i.scan_pass=2
        AND i.partition_name=d.first_partition AND i.page_no=d.first_page_no
        AND i.item_ordinal=d.first_item_ordinal AND i.provider_order_no=d.provider_order_no
    LEFT JOIN dp_pull_task t ON t.id=d.task_id
    WHERE NOT EXISTS (SELECT 1 FROM dp_pull_dp10_stage_cleanup m
        WHERE m.task_id=d.task_id AND m.generation_no=d.generation_no)
      AND (i.task_id IS NULL OR i.state<>'COMPLETE' OR i.verification_state<>'VERIFIED'
        OR t.id IS NULL OR t.operation_code<>'DP10' OR d.active_fence_epoch>t.fence_epoch)
  )
  AND NOT EXISTS (
    SELECT 1 FROM dp_pull_dp10_stage_item i LEFT JOIN dp_pull_dp10_stage_identity d
      ON d.task_id=i.task_id AND d.generation_no=i.generation_no AND d.provider_order_no=i.provider_order_no
        AND d.first_partition=i.partition_name AND d.first_page_no=i.page_no
        AND d.first_item_ordinal=i.item_ordinal
    WHERE NOT EXISTS (SELECT 1 FROM dp_pull_dp10_stage_cleanup m
        WHERE m.task_id=i.task_id AND m.generation_no=i.generation_no)
      AND i.scan_pass=2 AND i.state='COMPLETE' AND i.verification_state='VERIFIED' AND d.task_id IS NULL
  ),
  1, 0
) AS dp_pull_runtime_additive_livecheck;
